export interface PayIncluded {
  date: IsoDate;
  amount: Figure;
  late?: boolean;
}

/** Median and ± over the last 12 complete months, at the same point in the month. Null with under 6 months: no number, no colour. */
export interface UsualBand {
  median: number;
  /** The ±, in paise: the width that holds 8 of each 10 past misses, a rule and not a promise. Unrounded; the app rounds for show. */
  spread: number;
  n: number;
  hit_rate_bp: number;
  /** Which width made it. The back-test replaces this named input later. */
  method: string;
  at_day: number | null;
  /** The ladder against usual: z = (now - median) / ±, and the difference must be at least ₹2,000. */
  step: "r3" | "r2" | "r1" | "n" | "g1" | "g2" | null;
}

/** A payment as a memory cue, newest first, up to 12. */
export interface ReviewPayment {
  date: IsoDate;
  /** IST clock time where an SMS gave one. A statement alone gives a date. */
  time: string | null;
  key: string;
  amount: number;
  account: string | null;
  account_kind: "bank" | "card" | "other" | null;
}

export interface PriceRow {
  month: IsoMonth;
  amount: number;
}

export interface PaidLine {
  key: string;
  name: string;
  date: IsoDate;
  kind: "bill" | "sip" | "card_bill";
  account: string | null;
  account_kind: "bank" | "card" | "other" | null;
  /** A group from the ledger taxonomy with its detail: Food or Food:Groceries. Null only where no ledger account says, such as a plan. */
  category: string | null;
  /** Null while the merchant is unnamed or only suggested: a guess earns no logo. */
  brand: string | null;
  amount: Figure;
}

export interface YearlyBill {
  ym: IsoMonth;
  name: string;
  amount: Figure;
}

/** Price change in the holding's own currency since `since`: always shown with that date. Not a yearly return. */
export interface ReturnSince {
  since: IsoDate;
  from_price_date: IsoDate;
  bp: number | null;
}

/** Holdings in paise for Plan. `safe` is null: see `absent`. */
export interface Buckets {
  india: number | null;
  us: number | null;
  safe: number | null;
}

export interface MonthEnd {
  month: IsoMonth;
  balance: Figure;
}

/** The Line's past row: all bank money this month. */
export interface MonthSoFar {
  start: Figure | null;
  money_in: Figure;
  money_out: Figure;
}

export interface PlanPaid {
  txn: string;
  amount: number;
  ym: IsoMonth;
  source: "statement" | "sms";
}

/** A saved big expense, read back from the fold of plan.events.v1. Cancelled ones stay, as history. */
export interface Expense {
  id: string;
  rev: number;
  title: string;
  date: IsoDate | null;
  amount: Figure;
  ym: IsoMonth;
  by: IsoMonth | null;
  flex: "fixed" | "earlier" | "any";
  /** Months, in equal parts. */
  spread: number;
  status: "planned" | "paid" | "cancelled";
  note: string | null;
  paid: PlanPaid[];
  /** Paise still to come. */
  remaining: number;
  overdue: boolean;
  changed_elsewhere: boolean;
  source: "plan_events" | "plans_file";
}

export interface PlanNamed {
  name: string;
  amount: number;
}

export interface PlanPart {
  id: string;
  title: string;
  amount: number;
}

export interface PlanVest {
  ym: IsoMonth;
  date: IsoDate;
  instrument: string;
  amount: number;
  /** Not known from any source today. */
  spread: number | null;
}

export interface PlanBill {
  ym: IsoMonth;
  name: string;
  amount: number;
}

/** One month, in paise. open + salary + vests_in_cash - outgo - invest - bills - planned = end. Row 0 is Likely left, unrounded, with plans taken off. */
export interface YearRow {
  month: IsoMonth;
  open: number;
  salary: number;
  outgo: number;
  invest: number;
  bills: PlanNamed[];
  vests: PlanVest[];
  vests_in_cash: number;
  planned: PlanPart[];
  end_without_plans: number;
  end: number;
  spread: number;
  low: number;
  kind: "sell" | "dip" | "could" | "just" | "fits" | null;
  step: "r1" | "r2" | "r3" | "n" | "g1" | "g2" | null;
}

/** What the app's Plan engine needs, in paise, and 12 rows worked out from it. `rows` is empty when a needed input is null: see `absent`. */
export interface PlanYear {
  start: IsoMonth;
  open: number | null;
  first_salary: number | null;
  first_outgo: number | null;
  first_spread: number | null;
  takehome: number | null;
  outgo: number | null;
  outgo_spread: number | null;
  outgo_method: string | null;
  invest: number;
  invest_source: "entered" | "measured" | null;
  essentials: number | null;
  bills: PlanBill[];
  vests: PlanVest[];
  sell_vests: boolean;
  rows: YearRow[];
  /** The year again with row 0 as `forecast.before_salary`. Present when that figure is. */
  before_salary?: PlanYearBeforeSalary;
}

export interface PlanStore {
  events: number;
  invalid: number;
  torn: number;
  duplicates: number;
  ignored: number;
}

export interface PlanSettings {
  eq: number | null;
  sell_vests: boolean;
}

export interface AcceptedGap {
  account: string;
  covered_to: IsoDate;
  resumes: IsoDate;
}

export interface ReportMonth {
  month: IsoMonth;
  income: number;
  spent: number;
  invested: number;
  cash_in: number;
  cash_out: number;
  /** income - spent. */
  net: number;
  complete: boolean;
  unknown_in?: number;
}

export interface ReportPeriod {
  kind: "fy" | "calendar";
  label: string;
  from: IsoMonth;
  to: IsoMonth;
  /** False: some of it is not in the data or has not happened. Never show its sum as whole. */
  complete: boolean;
}

export interface AuditLine {
  date: IsoDate;
  key: string;
  kind: "income" | "spent" | "invested";
  name: string | null;
  account: string;
  amount: number;
  source: "statement" | "sms" | "splitwise";
  confidence: "statement" | "provisional" | "estimate";
  for_month?: IsoMonth;
}

export interface Audit {
  lines: AuditLine[];
  target_bp: number;
  /** Share of these rupees on a statement. */
  proven_bp: number | null;
}

export interface FlatMember {
  name: string;
  /** Paise. Above zero: is owed. */
  balance: number;
}

export interface FlatNet {
  name: string;
  net: number;
}

export interface FlatLine {
  date: IsoDate;
  title: string;
  cost: number;
  paid_by: string[];
  nets: FlatNet[];
  on_statement: null;
}

export interface FlatSettle {
  from: string;
  to: string;
  amount: number;
}

export interface FlatGroup {
  name: string;
  self: string;
  as_of: IsoDate | null;
  members: FlatMember[];
  lines: FlatLine[];
  settle: FlatSettle[];
  total: number;
}

export interface Flatmates {
  groups: FlatGroup[];
  source: "splitwise";
  confidence: "estimate";
}

/** Months from April of the last financial year. Cash flow and profit and loss sum `months`; Audit lists every line of income, spending and investing. */
export interface Reports {
  months: ReportMonth[];
  periods: ReportPeriod[];
  audit: Audit;
  flatmates: Flatmates | null;
  /** No source exists: see `absent`. */
  tax: null;
  unknown_in?: ({
    date: IsoDate;
    key: string;
    name: string | null;
    amount: number;
    source: string;
  })[];
}

export interface SalaryEve {
  month: IsoMonth;
  date: IsoDate;
  balance: Figure;
}

export interface BeforeSalary {
  /** See snapshot-v2.md. */
  definition: "before-salary-v1";
  /** The figure's day: the day before the next salary, or the month's last day when salary timing is unknown. Never before as_of. */
  date: IsoDate;
  basis: "salary" | "month_end";
  /** Why `date` is the month's last day. Null when it follows the salary. */
  date_reason: "no_regular_salary" | "salary_overdue" | null;
  /** cash - due - planned_moves - usual_spend, rounded to the rule's step. No salary is ever in it. Null when history is too short. */
  figure: Figure | null;
  status: CashStatus | null;
  /** The next salary: the Salary row after the figure. Null without a regular salary. */
  salary: SalaryLine | null;
  due: Figure | null;
  due_items: Item[];
  /** Repeating transfers to investing dated up to `date`. Known moves only: a one-off is never predicted. */
  planned_moves: Figure | null;
  planned_items: Item[];
  usual_spend: Figure | null;
  usual_spend_past: number[];
  moved_so_far: MovedSoFar;
  unplanned: UnplannedMoves;
  /** `due` is due_items less this. */
  payment_unmatched: PaymentUnmatched;
  if_salary_late?: {
    date: IsoDate;
    figure: number;
  } | null;
  /** How the range on `figure` is made, and how often it has held. Absent with no figure. */
  range?: UsualRange;
}

/** Paid to investing this month so far. Already out of cash, so already in the figure. */
export interface MovedSoFar {
  total: number;
  count: number;
}

/** Transfers to investing no repeating payment explains, over the last 12 covered months. NOT in the figure or its ±: any that happens lowers the real balance by that amount. Must be shown beside the figure when months_with is above 0. */
export interface UnplannedMoves {
  months: number;
  months_with: number;
  typical: number;
  largest: number;
  total: number;
}

export interface PlanYearBeforeSalary {
  date: IsoDate;
  first_salary: number;
  first_outgo: number;
  first_invest: number;
  first_spread: number;
  rows: YearRow[];
}

/** Bank debits classed as card payments that could name no card: part or round payments, or equal bills on two cards. Off the total once. Show as a line: "payment not yet matched to a card". */
export interface PaymentUnmatched {
  total: number;
  count: number;
}

export interface ShortfallFail {
  date: IsoDate;
  name: string;
  label?: string;
  amount: number;
  short: number;
}

/** Out of money, on the known schedule: snapshot-v2.md. Null with too little history to know a schedule. */
export interface Shortfall {
  definition: "shortfall-v1";
  active: boolean;
  until: IsoDate;
  below_zero: IsoDate | null;
  below_hard: IsoDate | null;
  first_fail: ShortfallFail | null;
  fails: ShortfallFail[];
  needed: number;
  lowest: number;
  holdings_to_sell?: boolean;
}

export interface SilentCard {
  card: string;
  account?: string;
  last_statement: IsoDate;
  due_date: IsoDate;
  unpaid: number;
  estimate: number;
}

export interface RollingUsual {
  median: number;
  spread: number;
  n: number;
  hit_rate_bp: number;
  method: string;
}

export interface RollingGroup {
  name: string;
  spent: Figure;
  usual: RollingUsual | null;
  verdict: "normal" | "above" | "below" | null;
}

export interface TrendMover {
  group: string;
  /** Paise, signed: up or down from the previous bar. */
  change: number;
}

/** [day of month, running total in paise], only on days the total changes. Before the first point it is 0. */
export type CurvePoints = number[][];

export interface MonthCurve {
  /** Null: all spending. */
  group: string | null;
  now: CurvePoints;
  past: {
    month: IsoMonth;
    points: CurvePoints;
    total: number;
    /** Paise of one-offs inside points and total, and left out of the median. */
    one_off: number;
  }[];
  /** Median per day of the past months without their one-offs. Null with too few months. */
  median: CurvePoints | null;
  median_n: number;
}

/** Running totals by day of month, for all spending and each group. snapshot-v2.md. */
export interface MonthCurves {
  definition: "month-curves-v1";
  months: IsoMonth[];
  curves: MonthCurve[];
}

/** Spend's opening: everyday spending in the running last 30 days against the usual 30 days. snapshot-v2.md. */
export interface Rolling {
  definition: "rolling-30-v1";
  days: number;
  from: IsoDate;
  to: IsoDate;
  spent: Figure;
  usual: RollingUsual | null;
  verdict: "normal" | "above" | "below" | null;
  without_one_offs: Figure;
  one_offs: Item[];
  excluded: {
    words: string[];
    amount: Figure;
  };
  groups: RollingGroup[];
  trend: ({
    date: IsoDate;
    spent: number | null;
    /** The group that changed this total most from the previous bar drawn. Null on a bar with no total, the first drawn, or when no group changed. Absent on a build from before this field. */
    mover?: TrendMover | null;
  })[];
  provisional_days: number;
  provisional_from: IsoDate | null;
  stale: boolean;
  /** The same 30 days and the same usual, both without one-offs (`spend_kind`), so the page compares like with like. snapshot-v2.md. */
  everyday?: {
    spent: number;
    one_off: number;
    usual: RollingUsual | null;
    verdict: "normal" | "above" | "below" | null;
    groups: ({
    name: string;
    spent: number;
    verdict: "normal" | "above" | "below" | null;
  })[];
  };
}

/** One payee in the fixed list. Amounts in paise. */
export interface FixedCost {
  name: string;
  group: string;
  category: string | null;
  brand: string | null;
  merchant_id: string | null;
  /** What a correction names: the merchant's alias key, or this payment. */
  key: string;
  /** Why, as a code. spend.allocation.reasons has the words. */
  spend_kind_reason: "owner" | "housing" | "fixed_account" | "recurs" | "varies" | "not_regular" | "thin_history" | "large" | "one_off_account";
  /** rule: worked out. owner: a correction with spend_kind said so. */
  spend_kind_source: "rule" | "owner";
  /** changed, twice and missing ask for attention. The rest stay quiet. */
  state: "steady" | "changed" | "twice" | "missing" | "due" | "new" | "stopped" | "occasional";
  cadence: "monthly" | "occasional";
  /** The latest month paid: for a rent, the month it is for. */
  month: IsoMonth;
  /** The newest payment's cash date. */
  date: IsoDate;
  /** What that month came to. For a split rent, the owner's share. */
  amount: number;
  /** Median of up to 6 earlier months, leaving out any paid twice. Null with none. */
  usual: number | null;
  /** This is a share of a payment split with others. */
  share: boolean;
  usual_day: number;
}

/** How Spend separates fixed costs, variable spending and large one-offs. snapshot-v2.md. */
export interface SpendAllocation {
  definition: "spend-kind-v1";
  rule: {
    recur_months: number;
    of_months: number;
    stable_bp: number;
    one_off_floor: number;
    one_off_bp: number;
    /** The one-off line used in this build, in paise. */
    one_off_threshold: number;
    usual_variable: number | null;
  };
  /** spend_kind_reason code -> its words. */
  reasons: Record<string, string>;
  fixed: {
    /** This month's fixed costs: paid so far, plus what is still to come at its usual. */
    monthly: number;
    paid: number;
    usual: number | null;
    /** same: nothing asks for attention. Null: no history to compare with. */
    verdict: "same" | "changed" | null;
    rows: FixedCost[];
  };
  /** What the running 30 days held of each kind. everyday is the part inside spend.rolling.spent, and sums to it. */
  window: {
    from: IsoDate;
    to: IsoDate;
    fixed: number;
    variable: number;
    one_off: number;
    everyday: {
    fixed: number;
    variable: number;
    one_off: number;
  };
  };
}

/** Measured in every build. The app words its label from these, so a stated hit rate cannot outlive its evidence. */
export interface UsualRange {
  /** Names the method, so an old range and a new one cannot be confused. */
  method: string;
  /** Past months that set the width. */
  months: number;
  /** Past months each judged by a range made only from the months before it. */
  tested: number;
  /** Of those, how many real balances landed inside. */
  held: number;
  /** The same with moves to investing and one-offs added back: how many usual months landed inside. */
  held_usual: number;
}

export interface LikelyBillRow {
  name: string;
  kind: "card_bill" | "card_bill_estimate" | "rent" | "fixed" | "flatmates_back";
  basis: "stated" | "estimated";
  /** When it falls due, or for rent and a share back, when it usually moves. */
  date: IsoDate;
  /** Out of the bank. A share coming back is negative. */
  amount: Figure;
  card: string | null;
  /** A card's charges since its last statement, for an estimated bill. */
  charges_so_far: number | null;
  brand: string | null;
}

/** See snapshot-v2.md, Likely bills. */
export interface LikelyBills {
  definition: "after-salary-v1";
  /** The next salary's day. */
  start: IsoDate;
  /** The day before the salary after it. */
  end: IsoDate;
  salary: number;
  /** Three in four card bills left within this many days of salary, in the last 6 pay cycles. Null with too few. */
  cards_within_days: number | null;
  /** The same for rent. */
  rent_within_days: number | null;
  items: LikelyBillRow[];
  /** The card rows alone. Bills reads this. */
  card_total: number;
  total: Figure;
  /** Likely left, plus the salary, less `total`. No everyday spending after salary is in it. */
  left: Figure;
}
